+// Audit log: records every request that changes data.
+
+/** Records an audit entry for a data-changing request. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Lists audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
