+// Bearer key authentication and role-based authorization.
+import { AppError } from "../errors.js";
+
+const ROLE_LEVEL = Object.freeze({ viewer: 1, cook: 2, manager: 3 });
+
+function bearerToken(headers = {}) {
+  const entry = Object.entries(headers).find(([k]) => k.toLowerCase() === "authorization");
+  if (!entry || typeof entry[1] !== "string") return null;
+  const m = /^Bearer\s+(.+)$/i.exec(entry[1].trim());
+  return m ? m[1].trim() : null;
+}
+
+/** Authenticates `headers` against `store.data.apiKeys`, returning the matching key record. */
+export function authenticate(store, headers) {
+  const token = bearerToken(headers);
+  if (!token) throw new AppError("unauthorized");
+  const key = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}
+
+/** Ensures `role` has at least `requiredRole` permission. */
+export function authorize(role, requiredRole) {
+  if ((ROLE_LEVEL[role] ?? 0) < (ROLE_LEVEL[requiredRole] ?? Infinity)) {
+    throw new AppError("forbidden");
+  }
+}
