+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("missing or unknown key returns 401", async () => {
+  const { handle } = app();
+  for (const headers of [{}, { authorization: "Basic abc" }, { authorization: "Bearer wrong-key" }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message);
+  }
+});
+
+test("viewer may only read (GET) and not GET /audit", async () => {
+  const { handle } = app();
+  const h = auth("viewer");
+  assert.equal((await handle({ path: "/items", headers: h })).status, 200);
+  for (const req of [
+    { method: "POST", path: "/recipes/1/cook", body: { portions: 1 } },
+    { method: "POST", path: "/batches/1/waste", body: { qty: 1 } },
+    { method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } },
+    { method: "POST", path: "/stocktakes/1/counts", body: { batchId: 1, counted: 1 } },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: h });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("cook may cook, waste, log temperatures and enter stock-take counts", async () => {
+  const { handle } = app();
+  const manager = auth("manager");
+  const cook = auth("cook");
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 1, counted: 4 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 2 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 0.5, reason: "spoiled" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 4 } })).status, 201);
+
+  for (const req of [
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: cook });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("audit logs data-changing requests newest first", async () => {
+  const { handle } = app();
+  const viewer = auth("viewer");
+  const cook = auth("cook");
+  const manager = auth("manager");
+
+  // GET and failed requests must not create audit entries.
+  await handle({ path: "/items", headers: viewer });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: cook, body: { portions: 100 } });
+  await handle({ method: "POST", path: "/orders", headers: cook, body: { supplierId: 1, lines: [] } });
+
+  await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3.2 } });
+  await handle({ method: "PUT", path: "/items/1/allergens", headers: manager, body: { allergens: ["celery"] } });
+
+  const auditRes = await handle({ path: "/audit", headers: manager });
+  assert.equal(auditRes.status, 200);
+  assert.equal(auditRes.body.length, 2);
+  assert.deepEqual(
+    auditRes.body.map(({ keyName, method, path, status, at }) => ({ keyName, method, path, status, at })),
+    [
+      { keyName: "manager", method: "PUT", path: "/items/1/allergens", status: 200, at: "2026-10-28T10:00:00.000Z" },
+      { keyName: "cook", method: "POST", path: "/temperatures", status: 201, at: "2026-10-28T10:00:00.000Z" },
+    ],
+  );
+});
